       <section id="app" class="faq-list" aria-label="Cat frequently asked questions"></section>
     </main>

     <script>
       const faqData = [
         {
           question: "Why do cats purr?",
           answer:
             "Cats purr for comfort, communication, and sometimes self-soothing. It can mean they are relaxed, asking for attention, or trying to feel better when stressed."
         },
         {
           question: "Do cats like being alone?",
           answer:
             "Many cats enjoy independent time, but most still want routine, enrichment, and social contact on their own terms. A cat may look solitary and still deeply appreciate company."
         },
         {
           question: "Why do cats knead blankets?",
           answer:
             "Kneading is a leftover kitten behavior linked to comfort and contentment. Adult cats often do it when they feel safe, cozy, or especially attached to their favorite spot."
         },
         {
           question: "How can I keep an indoor cat happy?",
           answer:
             "Offer climbing spaces, scratching posts, interactive play, window views, and a predictable feeding routine. A little variety every day helps prevent boredom."
         },
         {
           question: "Why do cats stare at me?",
           answer:
             "Cats often stare to read your movement, watch for cues, or simply because they are interested in what you are doing. Slow blinking back is a polite way to respond."
         },
         {
           question: "Are cats smart?",
           answer:
             "Yes—cats are highly observant learners. They may not always cooperate on command, but they are excellent at memory, pattern recognition, and solving problems that benefit them."
         }
       ];

       function createElement(tag, className, text) {
         const node = document.createElement(tag);
         if (className) node.className = className;
         if (text) node.textContent = text;
         return node;
       }

       function FAQItem({ question, answer }, index) {
         const item = createElement("div", "example");
         item.setAttribute("aria-expanded", "false");

         const button = createElement("button", "question");
         const id = `faq-answer-${index}`;
         button.type = "button";
         button.setAttribute("aria-expanded", "false");
         button.setAttribute("aria-controls", id);

         const label = createElement("strong", "", question);
         const icon = createElement("span", "chevron", "⌄");
         icon.setAttribute("aria-hidden", "true");

         button.append(label, icon);

         const details = createElement("div", "details");
         details.id = id;
         details.hidden = true;

         const paragraph = createElement("p", "", answer);
         details.append(paragraph);

         button.addEventListener("click", () => {
           const expanded = button.getAttribute("aria-expanded") === "true";
           button.setAttribute("aria-expanded", String(!expanded));
           item.setAttribute("aria-expanded", String(!expanded));
           details.hidden = expanded;
         });

         item.append(button, details);
         return item;
       }

       function App() {
         const fragment = document.createDocumentFragment();
         faqData.forEach((entry, index) => fragment.append(FAQItem(entry, index)));
         return fragment;
       }

       document.getElementById("app").append(App());
     </script>
   </body>
 </html>

')
